import React from 'react';
import { Link } from 'react-router-dom';
import '../App.css'; 

export default function Contact() {
  return (
    <div 
      className="bg-slate-950 text-slate-300 min-h-screen flex flex-col font-body-md relative"
      style={{
        backgroundSize: '32px 32px',
        backgroundImage: 'linear-gradient(to right, rgba(154, 143, 128, 0.15) 1px, transparent 1px), linear-gradient(to bottom, rgba(154, 143, 128, 0.15) 1px, transparent 1px)'
      }}
    >

      {/* Top NavBar */}
      <nav className="bg-slate-900/80 backdrop-blur-md font-body-md text-body-md docked full-width top-0 border-b border-slate-800 flex items-center w-full px-margin-desktop py-4 max-w-container-max mx-auto z-50 fixed justify-start relative transition-all">
        <div className="text-2xl md:text-3xl font-bold text-amber-400 tracking-tight relative z-10 ml-8">Duck</div>

        <div className="hidden md:flex absolute left-0 right-0 top-0 h-full z-0 pointer-events-none">
          <div className="flex-1 flex justify-end items-center pr-4 pointer-events-auto">
            <div className="flex space-x-6 items-center">
              <Link className="text-slate-400 hover:text-amber-400 transition-colors duration-200 scale-100 hover:scale-95 transition-all" to="/">Home</Link>
              <Link className="text-slate-400 hover:text-amber-400 transition-colors duration-200 scale-100 hover:scale-95 transition-all" to="/apply">Apply</Link>
              <Link className="text-slate-400 hover:text-amber-400 transition-colors duration-200 scale-100 hover:scale-95 transition-all" to="/outreach">Outreach</Link>
            </div>
          </div>
          <div className="flex-1 flex justify-start items-center pl-4 pointer-events-auto">
            <div className="flex space-x-6 items-center">
              <Link className="text-amber-400 border-b-2 border-amber-400 pb-1 hover:text-amber-300 transition-colors duration-200 scale-100 hover:scale-95 transition-all" to="/contact">Contact Us</Link>
              <a className="text-slate-400 hover:text-amber-400 transition-colors duration-200 scale-100 hover:scale-95 transition-all" href="/#sponsors">Sponsors</a>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content Canvas */}
      <main className="flex-grow pt-[140px] flex flex-col items-center justify-start px-margin-mobile md:px-margin-desktop w-full max-w-container-max mx-auto relative z-10 pb-24">

        {/* Contact Section */}
        <section id="contact" className="w-full max-w-5xl relative mx-auto px-6">
          <div className="flex flex-col items-center mb-12 text-center">
            <h2 className="text-4xl md:text-5xl font-bold text-slate-100 mb-4 tracking-tight">
              Contact Us
            </h2>
            <div className="w-24 h-1 bg-amber-500/50 rounded-full mb-6"></div>
            <p className="text-lg text-slate-400 max-w-2xl font-light">
              Have questions about our robot, outreach, or sponsorships? Send us a message and we'll get back to you.
            </p>
          </div>

          <div className="bg-slate-900 rounded-2xl border border-slate-800 p-8 md:p-12 shadow-xl shadow-black/40 max-w-3xl w-full mx-auto">
            <form 
              onSubmit={(e) => {
                e.preventDefault();
                const form = e.target;
                const submitBtn = form.querySelector('button[type="submit"]');
                const originalText = submitBtn.innerText;

                submitBtn.innerText = "Sending...";
                submitBtn.disabled = true;
                submitBtn.classList.add('opacity-70', 'cursor-not-allowed');

                // Google Script URL
                const scriptUrl = "https://script.google.com/macros/s/AKfycbyiWpPw0qMtkYenEjljpTJ1V1tRUZhPCSSO53qvzLZ8wzLisOx2YrRAchfaWGefnJc/exec";

                // EXACT FIX IS RIGHT HERE: Format data as URL parameters
                const data = new URLSearchParams(new FormData(form));

                fetch(scriptUrl, {
                  method: 'POST',
                  body: data,
                  mode: 'no-cors' 
                }).then(() => {
                  alert("Message sent successfully! Check your email for a confirmation.");
                  form.reset();
                  submitBtn.innerText = originalText;
                  submitBtn.disabled = false;
                  submitBtn.classList.remove('opacity-70', 'cursor-not-allowed');
                }).catch(error => {
                  console.error('Error!', error.message);
                  alert("Something went wrong. Please try again.");
                  submitBtn.innerText = originalText;
                  submitBtn.disabled = false;
                  submitBtn.classList.remove('opacity-70', 'cursor-not-allowed');
                });
              }}
              className="flex flex-col space-y-6"
            >

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex flex-col space-y-2 text-left">
                  <label className="text-slate-300 font-medium">Name</label>
                  <input 
                    type="text" 
                    name="name" 
                    required
                    className="bg-slate-950 border border-slate-800 rounded-lg p-3 text-slate-100 focus:outline-none focus:border-amber-400 focus:ring-1 focus:ring-amber-400 transition-all placeholder:text-slate-600" 
                    placeholder="Your name" 
                  />
                </div>
                <div className="flex flex-col space-y-2 text-left">
                  <label className="text-slate-300 font-medium">Email Address</label>
                  <input 
                    type="email" 
                    name="email" 
                    required
                    className="bg-slate-950 border border-slate-800 rounded-lg p-3 text-slate-100 focus:outline-none focus:border-amber-400 focus:ring-1 focus:ring-amber-400 transition-all placeholder:text-slate-600" 
                    placeholder="Your email" 
                  />
                </div>
              </div>

              <div className="flex flex-col space-y-2 text-left">
                <label className="text-slate-300 font-medium">Message</label>
                <textarea 
                  name="message"
                  required
                  rows="5" 
                  className="bg-slate-950 border border-slate-800 rounded-lg p-3 text-slate-100 focus:outline-none focus:border-amber-400 focus:ring-1 focus:ring-amber-400 transition-all resize-none placeholder:text-slate-600" 
                  placeholder="How can we help?"
                ></textarea>
              </div>

              <button 
                type="submit" 
                className="bg-amber-500 text-slate-950 px-8 py-4 rounded-lg font-bold text-lg hover:bg-amber-400 transition-colors mt-4 shadow-[0_0_15px_rgba(245,158,11,0.3)] w-full"
              >
                Send Message
              </button>
            </form>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="bg-slate-950 font-code-sm text-xs full-width bottom-0 border-t border-slate-800 flex items-center w-full px-8 py-8 max-w-container-max mx-auto mt-auto z-20 relative justify-center space-x-4">
        <div className="text-slate-500 font-semibold text-center uppercase tracking-wider">
          © 2026 FTC Team 30473
        </div>
        <div className="flex space-x-6 justify-center">
          <a className="text-slate-600 hover:text-amber-400 underline transition-colors" href="#privacy">
            Privacy Policy
          </a>
        </div>
      </footer>
    </div>
  );
}
